//! Helpers used by the code generated by the macros
//!
//! These are re-exported from `__private`, and are not covered by semver.

use postcard_schema_ng::{Schema, key::Key, schema::DataModelType};

use crate::{
    Request, RequestRaw,
    interface::{Method, MethodInfo},
    io::server::ServerError,
    wire::{HEADER_LEN, Header, Operation},
};

/// Check whether any duplicates are present in the given list.
///
/// Returns `false` if duplicates were found (NOT unique), otherwise returns
/// `true`.
pub const fn assert_unique(keys: &[Key]) -> bool {
    let mut i = 0;
    while i < keys.len() {
        let mut j = i + 1;
        let a = u64::from_le_bytes(keys[i].to_bytes());
        while j < keys.len() {
            let b = u64::from_le_bytes(keys[j].to_bytes());
            if a == b {
                return false;
            }
            j += 1;
        }
        i += 1;
    }
    true
}

/// Calculated the largest request body payload in bytes.
///
/// Returns `None` if one or more request type is unbounded.
pub const fn rqst_body_max_buf_required(infos: &[MethodInfo]) -> Option<usize> {
    // Ensure that buffers have AT LEAST enough for the WireError type
    let mut max = crate::wire::WireError::SCHEMA.max_size().unwrap();
    let mut idx = 0;
    while idx < infos.len() {
        let Some(m) = infos[idx].req_schema.max_size() else {
            return None;
        };
        if m > max {
            max = m;
        }
        idx += 1;
    }
    Some(max)
}

/// Calculated the largest response body payload in bytes.
///
/// Returns `None` if one or more response type is unbounded.
pub const fn resp_body_max_buf_required(infos: &[MethodInfo]) -> Option<usize> {
    // Ensure that buffers have AT LEAST enough for the WireError type
    let mut max = crate::wire::WireError::SCHEMA.max_size().unwrap();
    let mut idx = 0;
    while idx < infos.len() {
        let Some(m) = infos[idx].resp_schema.max_size() else {
            return None;
        };
        if m > max {
            max = m;
        }
        idx += 1;
    }
    Some(max)
}

/// Calculates the total number of `MethodInfo`s in an array of array of
/// `MethodInfo`s.
pub const fn total_len(sets: &[&[MethodInfo]]) -> usize {
    let mut i = 0;
    let mut ct = 0;
    while i < sets.len() {
        ct += sets[i].len();
        i += 1;
    }
    ct
}

/// Flattens an array of array of `MethodInfo`s into a flat array of `MethodInfo`s.
///
/// N should be the total length of `sets`, calculated by [`total_len()`].
pub const fn flatten<const N: usize>(sets: &[&[MethodInfo]]) -> [MethodInfo; N] {
    pub const ONE: MethodInfo = MethodInfo {
        name: "",
        key: Key::from_bytes([0; 8]),
        req_schema: &DataModelType::Unit,
        resp_schema: &DataModelType::Unit,
    };

    let mut out = [ONE; N];
    let mut i = 0;
    let mut n = 0;
    while i < sets.len() {
        let mut k = 0;
        while k < sets[i].len() {
            out[n] = sets[i][k];
            k += 1;
            n += 1;
        }
        i += 1;
    }
    assert!(n == N);
    out
}

/// Create an array of [`Key`]s from an array of [`MethodInfo`]s.
///
/// N must equal `infos.len()`.
pub const fn extract_keys<const N: usize>(infos: &[MethodInfo]) -> [Key; N] {
    assert!(N == infos.len());
    let mut buf = [Key::from_bytes([0u8; 8]); N];
    let mut idx = 0;
    while idx < N {
        buf[idx] = infos[idx].key;
        idx += 1;
    }
    buf
}

/// Handles the deserialization + serialization details when the specific method
/// has been selected to be dispatched to.
#[inline]
pub fn process_method_request<'rqst, 'resp, 'out, M: Method, F>(
    rqst_raw: RequestRaw<'rqst>,
    out: &'out mut [u8],
    func: F,
) -> Result<&'out [u8], ServerError>
where
    // The 'here lifetime encodes the lifetime of the borrow of the deserialized
    // request body. The body may contain borrows of the incoming request
    // buffer, basically `&'here Request<'rqst>` is passed to the dispatcher.
    //
    // This is a hrtb lifetime because we choose the lifetime inside of this
    // function, rather than based on something passed in like 'rqst or 'resp.
    F: for<'here> FnOnce(Request<'here, M::Request<'rqst>>) -> M::Response<'resp>,
{
    let RequestRaw { hedr, body } = rqst_raw;

    // Deserialize
    let (body, rest): (M::Request<'_>, _) =
        postcard::take_from_bytes(body).map_err(ServerError::RequestBodyDeserialize)?;
    if !rest.is_empty() {
        return Err(ServerError::RequestBodyTrailingBytes);
    }

    // Process request
    //
    // This is where the `'here` lifetime starts, with this borrow of the
    // deserialized request body.
    let rqst = Request { hedr, body: &body };
    let resp = func(rqst);
    // The `'here` lifetime could end here.

    // Avoid monomorphizing header writes
    let remain = write_response_header(hedr, out)?;
    let body_len = postcard::to_slice(&resp, remain)
        .map_err(ServerError::ResponseSerialize)?
        .len();
    Ok(&out[..HEADER_LEN + body_len])
}

/// Writes the response header for a given request header to the start of
/// `out`, returning the remaining bytes.
#[inline(never)]
fn write_response_header<'a>(
    rqst_hedr: &Header,
    out: &'a mut [u8],
) -> Result<&'a mut [u8], ServerError> {
    let hedr = Header {
        op: Operation::Response,
        ..*rqst_hedr
    };
    hedr.write_to(out)
        .map_err(ServerError::ResponseHeaderSerialize)
}
